// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns the production clock.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu        sync.Mutex
	rate      float64   // tokens per second
	burst     float64   // bucket capacity
	tokens    float64   // current tokens
	last      time.Time // last refill time
	clock     Clock
	nowFn     func() time.Time // for deterministic tests; overrides clock if set
	maxBurst  time.Duration    // cap on refill interval to bound work
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// (bucket capacity). The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		clock:  clock,
	}, nil
}

// AllowN reports whether n events are permitted at time now, consuming
// tokens if so. n must be positive; a non-positive n returns false.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single event is permitted now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// AllowNNow reports whether n events are permitted at the clock's current
// time, consuming tokens if so.
func (l *Limiter) AllowNNow(n int) bool {
	return l.AllowN(l.clock.Now(), n)
}

// Tokens returns the current number of available tokens (approximate under
// concurrency; refills lazily against now).
func (l *Limiter) Tokens(now time.Time) float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	return l.tokens
}

// refill advances the bucket state to time now. Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	if !now.After(l.last) {
		return
	}
	elapsed := now.Sub(l.last)
	// Bound refill work for arbitrarily long idle periods.
	if elapsed > 24*time.Hour {
		elapsed = 24 * time.Hour
	}
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
}
