// Package ratelimit implements a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by NewLimiter and is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	now      func() time.Time
}

// NewLimiter creates a Limiter that refills rate tokens per second, up to
// burst capacity. rate must be > 0 and burst must be >= 1.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst < 1 {
		return nil, errors.New("ratelimit: burst must be >= 1")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		now:    clock.Now,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, n tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since last refill.
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}

	if n < 0 || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
